sp_widget.client_script:
api.controller = function() {
  var c = this;

  var PAGE_IDS = {
    home:       'test_catalog',
    labReports: 'lab_reports'
  };

  c.loading = true;
  c.activeTab = 'all';
  c.searchQuery = '';
  c.sortBy = 'date_desc';
  c.filteredAppointments = [];
  c.showModal = false;
  c.selectedAppt = null;

  c.tabs = [
    { key: 'all',         label: 'All',         count: 0 },
    { key: 'Scheduled',   label: 'Scheduled',   count: 0 },
    { key: 'Confirmed',   label: 'Confirmed',   count: 0 },
    { key: 'InProgress',  label: 'In Progress', count: 0 },
    { key: 'Completed',   label: 'Completed',   count: 0 },
    { key: 'Cancelled',   label: 'Cancelled',   count: 0 }
  ];

  c.stats = [
    { icon: '📋', label: 'Total',      count: 0 },
    { icon: '🗓️', label: 'Scheduled',  count: 0 },
    { icon: '✅', label: 'Confirmed',  count: 0 },
    { icon: '✔️', label: 'Completed',  count: 0 }
  ];

  var _nav = function(pageId) {
    var portalId = window.location.pathname.split('/')[1] || 'sp';
    window.location.href = '/' + portalId + '?id=' + pageId;
  };

  c.$onInit = function() {
    c.loading = false;
    c.buildStats();
    c.filterAppointments();
  };

  c.buildStats = function() {
    var appts = c.data.appointments || [];
    c.stats[0].count = appts.length;
    c.stats[1].count = appts.filter(function(a) { return a.status === 'Scheduled'; }).length;
    c.stats[2].count = appts.filter(function(a) { return a.status === 'Confirmed'; }).length;
    c.stats[3].count = appts.filter(function(a) { return a.status === 'Completed'; }).length;
    c.tabs.forEach(function(tab) {
      tab.count = (tab.key === 'all')
        ? appts.length
        : appts.filter(function(a) { return a.status === tab.key; }).length;
    });
  };

  c.setTab = function(key) { c.activeTab = key; c.filterAppointments(); };

  c.filterAppointments = function() {
    var appts = angular.copy(c.data.appointments || []);
    var q   = (c.searchQuery || '').toLowerCase();
    var tab = c.activeTab;
    c.filteredAppointments = appts.filter(function(a) {
      var matchTab    = (tab === 'all') || (a.status === tab);
      var matchSearch = !q ||
        (a.test_name          && a.test_name.toLowerCase().indexOf(q) !== -1) ||
        (a.appointment_number && a.appointment_number.toLowerCase().indexOf(q) !== -1) ||
        (a.test_category      && a.test_category.toLowerCase().indexOf(q) !== -1);
      return matchTab && matchSearch;
    });
    c.sortAppointments();
  };

  c.sortAppointments = function() {
    c.filteredAppointments.sort(function(a, b) {
      if (c.sortBy === 'date_asc')  return (a.scheduled_date_display || '').localeCompare(b.scheduled_date_display || '');
      if (c.sortBy === 'date_desc') return (b.scheduled_date_display || '').localeCompare(a.scheduled_date_display || '');
      if (c.sortBy === 'status')    return (a.status || '').localeCompare(b.status || '');
      return 0;
    });
  };

  var STATUS_MAP = {
    'Scheduled':  { color:'#f59e0b', bg:'#fef3c7', icon:'🗓️', label:'Scheduled'    },
    'Confirmed':  { color:'#3b82f6', bg:'#dbeafe', icon:'✅', label:'Confirmed'   },
    'InProgress': { color:'#8b5cf6', bg:'#ede9fe', icon:'⏳', label:'In Progress' },
    'Completed':  { color:'#10b981', bg:'#dcfce7', icon:'✔️', label:'Completed'   },
    'Cancelled':  { color:'#6b7280', bg:'#f1f5f9', icon:'🚫', label:'Cancelled'   }
  };
  var _statusProp = function(s, prop, fallback) {
    return (STATUS_MAP[s] && STATUS_MAP[s][prop]) ? STATUS_MAP[s][prop] : fallback;
  };
  c.getStatusColor = function(s) { return _statusProp(s, 'color', '#94a3b8'); };
  c.getStatusBg    = function(s) { return _statusProp(s, 'bg',    '#f1f5f9'); };
  c.getStatusIcon  = function(s) { return _statusProp(s, 'icon',  '•');       };
  c.getStatusLabel = function(s) { return _statusProp(s, 'label', s);         };

  c.getApprovalLabel = function(s) {
    var m = { 'Pending':'Approval Pending', 'Approved':'✅ Approved', 'Rejected':'❌ Rejected', 'Completed':'Approved & Completed', 'Cancelled':'Cancelled' };
    return m[s] || s;
  };

  c.getPaymentLabel = function(s) {
    var m = { 'Pending':'Payment Pending', 'Paid':'✓ Paid', 'Failed':'Payment Failed', 'Refunded':'Refunded' };
    return m[s] || (s || 'N/A');
  };

  c.getCategoryIcon = function(cat) {
    var icons = { 'blood':'🩸','urine':'🧪','imaging':'🩻','cardiology':'❤️',
                  'neurology':'🧠','genetics':'🧬','pathology':'🔬' };
    if (!cat) return '🔬';
    var k = cat.toLowerCase();
    for (var key in icons) { if (k.indexOf(key) !== -1) return icons[key]; }
    return '🔬';
  };

  c.canCancel = function(appt) {
    return appt.status === 'Scheduled' || appt.status === 'Confirmed';
  };

  c.cancelAppointment = function(appt) {
    if (!confirm('Are you sure you want to cancel appointment ' + appt.appointment_number + '?')) return;
    c.server.get({ action: 'cancel_appointment', appointment_sys_id: appt.sys_id })
      .then(function(response) {
        if (response.data.success) {
          appt.status = 'Cancelled';
          c.buildStats();
          c.filterAppointments();
          alert('Appointment cancelled successfully.');
        } else {
          alert('Error: ' + (response.data.error || 'Failed to cancel.'));
        }
      });
  };

  c.viewDetails = function(appt) { c.selectedAppt = appt; c.showModal = true;  };
  c.closeModal  = function()     { c.showModal = false;   c.selectedAppt = null; };

  c.bookNew    = function() { _nav(PAGE_IDS.home); };
  c.viewReport = function(appt) { _nav(PAGE_IDS.labReports); };
};

sp_widget.css:
.my-appts {
  --primary: #0a2463;
  --accent: #00b4d8;
  --success: #10b981;
  --warning: #f59e0b;
  --danger: #ef4444;
  --info: #3b82f6;
  --gray-50: #f8fafc;
  --gray-100: #f1f5f9;
  --gray-200: #e2e8f0;
  --gray-400: #94a3b8;
  --gray-600: #475569;
  --gray-800: #1e293b;
  --white: #ffffff;
  --shadow-sm: 0 1px 4px rgba(0,0,0,0.07);
  --shadow-md: 0 4px 14px rgba(0,0,0,0.09);
  --radius: 14px;
  font-family: 'Segoe UI', system-ui, sans-serif;
  background: var(--gray-50);
  min-height: 100vh;
  padding: 0 0 60px;
}

/* ---------- HEADER ---------- */
.my-appts .appts-header {
  background: linear-gradient(135deg, var(--primary) 0%, #1e3a8a 100%);
  padding: 40px 40px 50px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  border-radius: 0 0 32px 32px;
  flex-wrap: wrap;
  gap: 20px;
}
.my-appts .header-title { font-size: 32px; font-weight: 800; color: var(--white); margin: 0 0 8px; }
.my-appts .header-sub { color: #bfdbfe; margin: 0; font-size: 15px; }
.my-appts .btn-book-new {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 12px 24px; background: var(--accent); color: var(--white);
  border: none; border-radius: 10px; font-size: 15px; font-weight: 700;
  cursor: pointer; transition: all 0.2s;
  box-shadow: 0 4px 14px rgba(0,180,216,0.35); white-space: nowrap;
}
.my-appts .btn-book-new:hover { transform: translateY(-2px); box-shadow: 0 6px 20px rgba(0,180,216,0.45); }

/* ---------- STATS BAR ---------- */
.my-appts .stats-bar { display: flex; gap: 16px; padding: 24px 40px 0; flex-wrap: wrap; }
.my-appts .stat-card {
  flex: 1; min-width: 120px; background: var(--white); border-radius: var(--radius);
  border: 1px solid var(--gray-200); padding: 16px 20px; display: flex;
  align-items: center; gap: 14px; box-shadow: var(--shadow-sm); transition: box-shadow 0.2s;
}
.my-appts .stat-card:hover { box-shadow: var(--shadow-md); }
.my-appts .stat-icon { font-size: 28px; }
.my-appts .stat-info { display: flex; flex-direction: column; }
.my-appts .stat-val { font-size: 22px; font-weight: 800; color: var(--primary); line-height: 1; }
.my-appts .stat-name { font-size: 12px; color: var(--gray-600); font-weight: 500; margin-top: 2px; }

/* ---------- FILTER TABS ---------- */
.my-appts .filter-tabs { display: flex; gap: 8px; padding: 24px 40px 0; flex-wrap: wrap; }
.my-appts .filter-tab {
  display: inline-flex; align-items: center; gap: 6px; padding: 8px 18px;
  border-radius: 24px; border: 2px solid var(--gray-200); background: var(--white);
  color: var(--gray-600); font-size: 14px; font-weight: 600; cursor: pointer; transition: all 0.2s;
}
.my-appts .filter-tab:hover { border-color: var(--accent); color: var(--accent); }
.my-appts .filter-tab.active {
  background: var(--primary); border-color: var(--primary); color: var(--white);
  box-shadow: 0 4px 12px rgba(10,36,99,0.25);
}
.my-appts .tab-count { background: rgba(255,255,255,0.25); border-radius: 12px; padding: 1px 7px; font-size: 11px; font-weight: 700; }
.my-appts .filter-tab:not(.active) .tab-count { background: var(--gray-100); color: var(--gray-600); }

/* ---------- LIST CONTROLS ---------- */
.my-appts .list-controls { display: flex; align-items: center; gap: 12px; padding: 16px 40px; flex-wrap: wrap; }
.my-appts .search-mini-wrap { position: relative; flex: 1; max-width: 320px; }
.my-appts .search-mini-wrap .fa { position: absolute; left: 12px; top: 50%; transform: translateY(-50%); color: var(--gray-400); }
.my-appts .search-mini {
  padding: 9px 14px 9px 36px; border: 2px solid var(--gray-200); border-radius: 8px;
  font-size: 14px; width: 100%; outline: none; transition: border-color 0.2s; box-sizing: border-box;
}
.my-appts .search-mini:focus { border-color: var(--accent); }
.my-appts .sort-mini {
  padding: 9px 14px; border: 2px solid var(--gray-200); border-radius: 8px;
  font-size: 14px; background: var(--white); cursor: pointer; outline: none;
}
.my-appts .sort-mini:focus { border-color: var(--accent); }

/* ---------- LOADING ---------- */
.my-appts .loading-center { text-align: center; padding: 60px; color: var(--gray-600); }
.my-appts .spinner-ring {
  display: inline-block; width: 44px; height: 44px; border: 4px solid var(--gray-200);
  border-top-color: var(--accent); border-radius: 50%;
  animation: myApptsSpin 0.8s linear infinite; margin-bottom: 14px;
}
@keyframes myApptsSpin { to { transform: rotate(360deg); } }

/* ---------- EMPTY STATE ---------- */
.my-appts .empty-appts { text-align: center; padding: 60px 40px; }
.my-appts .empty-emoji { font-size: 56px; margin-bottom: 16px; }
.my-appts .empty-appts h3 { font-size: 20px; color: var(--gray-800); margin: 0 0 8px; }
.my-appts .empty-appts p { color: var(--gray-600); margin: 0 0 20px; }
.my-appts .btn-book-first {
  padding: 12px 28px; background: var(--primary); color: var(--white); border: none;
  border-radius: 10px; font-size: 15px; font-weight: 700; cursor: pointer; transition: background 0.2s;
}
.my-appts .btn-book-first:hover { background: #1e3a8a; }

/* ---------- APPOINTMENTS LIST ---------- */
.my-appts .appts-list { padding: 8px 40px; display: flex; flex-direction: column; gap: 16px; }

/* ---------- APPOINTMENT CARD ---------- */
.my-appts .appt-card {
  background: var(--white); border-radius: var(--radius); border: 1px solid var(--gray-200);
  display: flex; overflow: hidden; box-shadow: var(--shadow-sm);
  transition: box-shadow 0.2s, transform 0.2s;
}
.my-appts .appt-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.my-appts .appt-accent-bar { width: 5px; flex-shrink: 0; }
.my-appts .appt-content { flex: 1; padding: 20px 24px; }

/* TOP ROW */
.my-appts .appt-top { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: 14px; gap: 12px; flex-wrap: wrap; }
.my-appts .appt-title-group { display: flex; align-items: center; gap: 14px; }
.my-appts .appt-icon { font-size: 32px; }
.my-appts .appt-test-name { font-size: 17px; font-weight: 700; color: var(--gray-800); margin: 0 0 4px; }
.my-appts .appt-number { font-size: 12px; color: var(--gray-400); font-family: 'Courier New', monospace; }
.my-appts .appt-status-wrap { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }

/* STATUS PILLS */
.my-appts .status-pill {
  display: inline-flex; align-items: center; gap: 5px; padding: 5px 14px;
  border-radius: 20px; font-size: 12px; font-weight: 700; text-transform: capitalize;
}
.my-appts .approval-pill { padding: 4px 12px; border-radius: 20px; font-size: 11px; font-weight: 700; text-transform: capitalize; }

/* Corrected to match the REAL stored Choice values: Pending, Approved, Completed, Cancelled, Rejected */
.my-appts .approval-Pending   { background: var(--warning); background: #fef3c7; color: #92400e; }
.my-appts .approval-Approved  { background: #dcfce7; color: #166534; }
.my-appts .approval-Completed { background: #dbeafe; color: #1d4ed8; }
.my-appts .approval-Cancelled { background: var(--gray-100); color: var(--gray-600); }
.my-appts .approval-Rejected  { background: var(--danger); background: #fee2e2; color: #991b1b; }

/* META ROW */
.my-appts .appt-meta { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 12px; }
.my-appts .meta-chip {
  display: inline-flex; align-items: center; gap: 5px; font-size: 13px; color: var(--gray-600);
  background: var(--gray-100); padding: 4px 10px; border-radius: 6px;
}
.my-appts .meta-chip .fa { color: var(--accent); font-size: 12px; }

/* INFO ROW */
.my-appts .appt-info-row { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 10px; }
.my-appts .info-badge { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; padding: 4px 10px; border-radius: 6px; font-weight: 500; }
.my-appts .pay-paid { background: #dcfce7; color: #166534; }
.my-appts .pay-pending { background: #fef3c7; color: #92400e; }
.my-appts .pay-unpaid { background: var(--danger); background: #fee2e2; color: #991b1b; }
.my-appts .approval-info { background: var(--info); background: #dbeafe; color: #1d4ed8; }
.my-appts .conf-badge { background: #f0fdf4; color: #166534; }

/* NOTES */
.my-appts .appt-notes {
  font-size: 13px; color: var(--gray-600); background: var(--gray-50);
  border-left: 3px solid var(--gray-200); padding: 6px 12px; margin-bottom: 12px;
  border-radius: 0 6px 6px 0; font-style: italic;
}

/* REJECTION BANNER */
.my-appts .rejection-banner {
  display: flex; align-items: flex-start; gap: 10px; background: #fef2f2;
  border: 1px solid #fecaca; border-radius: 8px; padding: 10px 14px;
  margin-bottom: 12px; font-size: 13px; color: #991b1b;
}

/* ACTIONS */
.my-appts .appt-actions { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.my-appts .appt-action-btn {
  display: inline-flex; align-items: center; gap: 6px; padding: 7px 16px;
  border-radius: 8px; font-size: 13px; font-weight: 600; cursor: pointer; border: none; transition: all 0.2s;
}
.my-appts .btn-view { background: #dbeafe; color: #1d4ed8; }
.my-appts .btn-view:hover { background: #bfdbfe; }
.my-appts .btn-cancel { background: #fee2e2; color: #b91c1c; }
.my-appts .btn-cancel:hover { background: #fecaca; }
.my-appts .btn-report { background: #dcfce7; color: #166534; }
.my-appts .btn-report:hover { background: #bbf7d0; }
.my-appts .date-chip { margin-left: auto; font-size: 11px; color: var(--gray-400); white-space: nowrap; }

/* ---------- MODAL ---------- */
.my-appts .modal-overlay {
  position: fixed; inset: 0; background: rgba(0,0,0,0.5); z-index: 9999;
  display: flex; align-items: center; justify-content: center; padding: 20px;
}
.my-appts .modal-box {
  background: var(--white); border-radius: 20px; max-width: 560px; width: 100%;
  overflow: hidden; box-shadow: 0 20px 60px rgba(0,0,0,0.25); animation: myApptsSlideUp 0.3s ease;
}
@keyframes myApptsSlideUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
.my-appts .modal-header { display: flex; align-items: center; justify-content: space-between; padding: 20px 24px; background: var(--primary); color: var(--white); }
.my-appts .modal-header h3 { margin: 0; font-size: 18px; }
.my-appts .modal-close { background: none; border: none; color: var(--white); font-size: 20px; cursor: pointer; line-height: 1; opacity: 0.8; transition: opacity 0.2s; }
.my-appts .modal-close:hover { opacity: 1; }
.my-appts .modal-body { padding: 24px; }
.my-appts .detail-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.my-appts .detail-item { display: flex; flex-direction: column; gap: 4px; }
.my-appts .detail-item.full { grid-column: 1 / -1; }
.my-appts .detail-key { font-size: 11px; font-weight: 700; text-transform: uppercase; color: var(--gray-400); letter-spacing: 0.4px; }
.my-appts .detail-val { font-size: 14px; font-weight: 600; color: var(--gray-800); }
.my-appts .detail-val.mono { font-family: 'Courier New', monospace; color: var(--primary); }
.my-appts .detail-val.paid-green { color: var(--success); font-size: 16px; }
.my-appts .modal-footer { padding: 16px 24px; border-top: 1px solid var(--gray-100); display: flex; justify-content: flex-end; }
.my-appts .btn-close-modal { padding: 10px 24px; background: var(--primary); color: var(--white); border: none; border-radius: 8px; font-weight: 700; cursor: pointer; transition: background 0.2s; }
.my-appts .btn-close-modal:hover { background: #1e3a8a; }

/* ---------- RESPONSIVE ---------- */
@media (max-width: 768px) {
  .my-appts .appts-header, .my-appts .stats-bar, .my-appts .filter-tabs, .my-appts .list-controls, .my-appts .appts-list {
    padding-left: 16px; padding-right: 16px;
  }
  .my-appts .stats-bar { gap: 10px; }
  .my-appts .stat-card { min-width: 100px; }
  .my-appts .appt-top { flex-direction: column; }
  .my-appts .date-chip { margin-left: 0; }
  .my-appts .detail-grid { grid-template-columns: 1fr; }
}

sp_widget.script:
(function() {
  data.appointments = [];

  try {
    var currentUser  = gs.getUser();
    var userID       = gs.getUserID();
    var userEmail    = currentUser.getEmail() || '';

    var patientSysIds = [];
    var patientMap    = {};

    var patGr = new GlideRecord('x_2133481_medica_0_patient'); // CONFIRM this table name
    patGr.addQuery('user', userID);
    patGr.query();
    while (patGr.next()) {
      var pid = patGr.getUniqueValue();
      if (!patientMap[pid]) { patientMap[pid] = true; patientSysIds.push(pid); }
    }

    if (userEmail) {
      var patEmailGr = new GlideRecord('x_2133481_medica_0_patient');
      patEmailGr.addQuery('email', userEmail);
      patEmailGr.query();
      while (patEmailGr.next()) {
        var eid = patEmailGr.getUniqueValue();
        if (!patientMap[eid]) { patientMap[eid] = true; patientSysIds.push(eid); }
      }
    }

    var apptSysIds  = [];
    var apptMap     = {};

    var createdByGr = new GlideRecord('x_2133481_medica_0_appointment_table');
    createdByGr.addQuery('created_by', userID);
    createdByGr.orderByDesc('sys_created_on');
    createdByGr.query();
    while (createdByGr.next()) {
      var aid = createdByGr.getUniqueValue();
      if (!apptMap[aid]) {
        apptMap[aid] = true;
        apptSysIds.push(aid);
        var pRef = createdByGr.getValue('patient');
        if (pRef && !patientMap[pRef]) {
          patientMap[pRef] = true;
          patientSysIds.push(pRef);
        }
      }
    }

    if (patientSysIds.length > 0) {
      var apptPatGr = new GlideRecord('x_2133481_medica_0_appointment_table');
      apptPatGr.addQuery('patient', 'IN', patientSysIds.join(','));
      apptPatGr.orderByDesc('sys_created_on');
      apptPatGr.query();
      while (apptPatGr.next()) {
        var apid = apptPatGr.getUniqueValue();
        if (!apptMap[apid]) {
          apptMap[apid] = true;
          apptSysIds.push(apid);
        }
      }
    }

    if (apptSysIds.length === 0) {
      data.appointments = [];
      return;
    }

    var finalGr = new GlideRecord('x_2133481_medica_0_appointment_table');
    finalGr.addQuery('sys_id', 'IN', apptSysIds.join(','));
    finalGr.orderByDesc('sys_created_on');
    finalGr.query();

    while (finalGr.next()) {

      var testName     = '';
      var testCategory = '';
      var testRef      = finalGr.getValue('test');
      if (testRef) {
        var testGr = new GlideRecord('x_2133481_medica_0_diagnostic_test');
        if (testGr.get(testRef)) {
          testName     = testGr.getValue('test_name') || '';
          testCategory = testGr.getDisplayValue('category') || testGr.getValue('category') || '';
        }
      }

      var hasReport = false;
      var reportGr  = new GlideRecord('x_2133481_medica_0_report_table');
      reportGr.addQuery('appointment', finalGr.getUniqueValue());
      reportGr.setLimit(1);
      reportGr.query();
      if (reportGr.next()) { hasReport = true; }

      var approvedByName = '';
      var approvedByRef  = finalGr.getValue('approved_by');
      if (approvedByRef) {
        var approverGr = new GlideRecord('sys_user');
        if (approverGr.get(approvedByRef)) {
          approvedByName = approverGr.getDisplayValue('name') || '';
        }
      }

      var scheduledDisplay = finalGr.getDisplayValue('scheduled_date') || '';

      data.appointments.push({
        sys_id:                 finalGr.getUniqueValue(),
        appointment_number:     finalGr.getValue('appointment_number') || '',
        status:                 finalGr.getValue('status') || '',
        approval_status:        finalGr.getValue('approval_status') || '',
        payment_status:         finalGr.getValue('payment_status') || '',
        scheduled_date_display: scheduledDisplay,
        slot_time:              finalGr.getDisplayValue('slot_time') || '',
        total_amount:           parseFloat(finalGr.getValue('total_amount')) || 0,
        notes:                  finalGr.getValue('notes') || '',
        rejection_reason:       finalGr.getValue('rejection_reason') || '',
        confirmation_sent:      finalGr.getValue('confirmation_sent') === '1' || finalGr.getValue('confirmation_sent') === true,
        test_name:              testName,
        test_category:          testCategory,
        approved_by_name:       approvedByName,
        has_report:             hasReport,
        created_on_display:     finalGr.getDisplayValue('sys_created_on') || ''
      });
    }

    if (input && input.action === 'cancel_appointment') {
      var cancelGr = new GlideRecord('x_2133481_medica_0_appointment_table');
      if (cancelGr.get(input.appointment_sys_id)) {

        var isOwner = false;
        if (cancelGr.getValue('created_by') === userID) {
          isOwner = true;
        } else {
          var cancelPatId = cancelGr.getValue('patient');
          if (cancelPatId && patientSysIds.indexOf(cancelPatId) !== -1) {
            isOwner = true;
          }
        }

        if (isOwner) {
          cancelGr.setValue('status', 'Cancelled'); // FIXED: capital C, matches real Status value
          cancelGr.update();
          data.success = true;

          try {
            var patEmail2 = '';
            var patGr2 = new GlideRecord('x_2133481_medica_0_patient');
            if (patGr2.get(cancelGr.getValue('patient'))) {
              patEmail2 = patGr2.getValue('email') || '';
            }
            if (patEmail2) {
              var emailer = new GlideEmailOutbound();
              emailer.setTo(patEmail2);
              emailer.setSubject('Appointment Cancelled: ' + cancelGr.getValue('appointment_number'));
              emailer.setBody('<p>Your appointment <strong>' +
                cancelGr.getValue('appointment_number') +
                '</strong> has been cancelled. If this was a mistake, please book again.</p>');
              emailer.save();
            }
          } catch (emailErr) {
            gs.warn('Cancel email error: ' + emailErr.message);
          }

        } else {
          data.error = 'Unauthorized';
        }
      } else {
        data.error = 'Appointment not found';
      }
    }

  } catch (e) {
    gs.error('My Appointments Widget Error: ' + e.message);
    data.error = 'Failed to load appointments: ' + e.message;
    data.appointments = [];
  }
})();
